import { SEMANTIC_COLOR_KEYS } from "@launchbed/schema";
import type { ThemeTokens } from "./index";

export function toKotlinColor(hex: string): string {
  return `0xFF${hex.replace("#", "").toUpperCase()}`;
}

export const GENERATED_HEADER = "// Generated by Launchbed from DTCG tokens via Style Dictionary 5. Do not edit by hand.";
export const GENERATED_CSS_HEADER =
  "/* Generated by Launchbed from DTCG tokens via Style Dictionary 5. Do not edit by hand. */";

export interface TokenValue {
  path: readonly string[];
  type: string;
  value: string;
}

export function tokenKey(path: readonly string[]): string {
  return path.join(".");
}

function kotlinTokenName(key: string): string {
  return key.charAt(0).toUpperCase() + key.slice(1);
}

function camelFromPath(path: readonly string[]): string {
  return path
    .map((part, index) => (index === 0 ? part : part.charAt(0).toUpperCase() + part.slice(1)))
    .join("");
}

function kebabFromPath(path: readonly string[]): string {
  return path
    .join("-")
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .toLowerCase();
}

/** Shared Compose color file used by Style Dictionary and the ThemeTokens helper. */
export function formatComposeColors(tokens: ThemeTokens, packageName: string): string {
  const lines: string[] = [
    `package ${packageName}.ui.theme`,
    "",
    "import androidx.compose.ui.graphics.Color",
    "",
    GENERATED_HEADER,
  ];
  for (const mode of ["Light", "Dark"] as const) {
    const scheme = mode === "Light" ? tokens.light : tokens.dark;
    lines.push("", `// ${mode} scheme (seed ${tokens.seedColor}, ${tokens.schemeVariant})`);
    for (const key of SEMANTIC_COLOR_KEYS) {
      lines.push(`internal val ${mode}${kotlinTokenName(key)} = Color(${toKotlinColor(scheme[key])})`);
    }
  }
  lines.push("");
  return lines.join("\n");
}

/** Shared Compose spacing/shape file used by Style Dictionary and the ThemeTokens helper. */
export function formatComposeTokens(tokens: ThemeTokens, packageName: string): string {
  const { spacing, shape, components } = tokens;
  const fontFamily =
    tokens.typography.fontFamily === "monospace"
      ? "FontFamily.Monospace"
      : tokens.typography.fontFamily === "serif"
        ? "FontFamily.Serif"
        : tokens.typography.fontFamily === "sansSerif"
          ? "FontFamily.SansSerif"
          : "FontFamily.Default";
  const lines: string[] = [
    `package ${packageName}.ui.theme`,
    "",
    "import androidx.compose.ui.text.font.FontFamily",
    "import androidx.compose.ui.unit.dp",
    "",
    GENERATED_HEADER,
    `internal val AppFontFamily = ${fontFamily}`,
    `internal val BaseCornerRadius = ${shape.cornerRadius}.dp`,
    "",
    "internal object Spacing {",
    `    val xs = ${spacing.xs}.dp`,
    `    val sm = ${spacing.sm}.dp`,
    `    val md = ${spacing.md}.dp`,
    `    val lg = ${spacing.lg}.dp`,
    `    val xl = ${spacing.xl}.dp`,
    "}",
    "",
    "internal object ComponentTokens {",
    `    val cardCornerRadius = ${components.card.cornerRadius}.dp`,
    `    val cardElevation = ${components.card.elevation}.dp`,
    `    val buttonCornerRadius = ${components.button.cornerRadius}.dp`,
    `    val buttonMinHeight = ${components.button.minHeight}.dp`,
    "}",
    "",
  ];
  return lines.join("\n");
}

export function themeTokensFromValueMap(values: Map<string, string>): ThemeTokens {
  const scheme = (mode: "light" | "dark") => {
    const colors = {} as ThemeTokens["light"];
    for (const key of SEMANTIC_COLOR_KEYS) {
      const value = values.get(`color.${mode}.${key}`);
      if (!value) throw new Error(`Missing DTCG color token color.${mode}.${key}`);
      colors[key] = value.toUpperCase();
    }
    return colors;
  };
  const px = (path: string): number => {
    const raw = values.get(path);
    if (!raw) throw new Error(`Missing DTCG dimension token ${path}`);
    const match = /^(\d+(?:\.\d+)?)px$/.exec(raw);
    if (!match) throw new Error(`DTCG token ${path} is not a px dimension: ${raw}`);
    return Number(match[1]);
  };
  const seed = values.get("color.seed");
  const variant = values.get("meta.schemeVariant");
  const mode = values.get("meta.defaultMode");
  const font = values.get("fontFamily.plain");
  if (!seed || !variant || !mode || !font) {
    throw new Error("DTCG document is missing seed, typography or meta tokens.");
  }
  return {
    seedColor: seed.toUpperCase(),
    schemeVariant: variant as ThemeTokens["schemeVariant"],
    defaultMode: mode as ThemeTokens["defaultMode"],
    light: scheme("light"),
    dark: scheme("dark"),
    typography: { fontFamily: font as ThemeTokens["typography"]["fontFamily"] },
    shape: { cornerRadius: px("dimension.shape.cornerRadius") },
    spacing: {
      xs: px("dimension.spacing.xs"),
      sm: px("dimension.spacing.sm"),
      md: px("dimension.spacing.md"),
      lg: px("dimension.spacing.lg"),
      xl: px("dimension.spacing.xl"),
    },
    components: {
      card: {
        cornerRadius: px("dimension.component.card.cornerRadius"),
        elevation: px("dimension.component.card.elevation"),
      },
      button: {
        cornerRadius: px("dimension.component.button.cornerRadius"),
        minHeight: px("dimension.component.button.minHeight"),
      },
    },
  };
}

function cssValue(token: TokenValue): string {
  if (token.type === "string" || token.type === "fontFamily") {
    const needsQuote = /[\s,]/.test(token.value) && !token.value.startsWith("\"");
    return needsQuote ? `"${token.value.replaceAll("\"", "\\\"")}"` : token.value;
  }
  return token.value;
}

function flutterValue(token: TokenValue): string {
  if (token.type === "color" && token.value.startsWith("#")) {
    const hex = token.value.replace("#", "").toUpperCase();
    return `Color(0xFF${hex})`;
  }
  if (token.type === "dimension") {
    const match = /^(\d+(?:\.\d+)?)px$/.exec(token.value);
    if (!match) throw new Error(`Cannot emit Flutter dimension for ${token.path.join(".")}: ${token.value}`);
    const n = match[1];
    if (!n) throw new Error(`Cannot emit Flutter dimension for ${token.path.join(".")}: ${token.value}`);
    return n.includes(".") ? n : `${n}.0`;
  }
  return JSON.stringify(token.value);
}

/** Deterministic CSS custom properties for a future web/CSS target. */
export function formatCssVariables(tokens: readonly TokenValue[]): string {
  const sorted = [...tokens].sort((a, b) => tokenKey(a.path).localeCompare(tokenKey(b.path)));
  const lines = [
    GENERATED_CSS_HEADER,
    ":root {",
    ...sorted.map((token) => `  --${kebabFromPath(token.path)}: ${cssValue(token)};`),
    "}",
    "",
  ];
  return lines.join("\n");
}

/** Deterministic Dart constants for a future Flutter target. */
export function formatFlutterDart(tokens: readonly TokenValue[]): string {
  const sorted = [...tokens].sort((a, b) => tokenKey(a.path).localeCompare(tokenKey(b.path)));
  const hasColor = sorted.some((token) => token.type === "color");
  const lines = [
    GENERATED_HEADER,
    ...(hasColor ? ["import 'package:flutter/material.dart';", ""] : []),
    "class LaunchbedTokens {",
    "  LaunchbedTokens._();",
    ...sorted.map((token) => {
      const name = camelFromPath(token.path);
      if (token.type === "color") return `  static const Color ${name} = ${flutterValue(token)};`;
      if (token.type === "dimension") return `  static const double ${name} = ${flutterValue(token)};`;
      return `  static const String ${name} = ${flutterValue(token)};`;
    }),
    "}",
    "",
  ];
  return lines.join("\n");
}
